package com.flippingfriend.companion;
import java.util.ArrayList; import java.util.Collections; import java.util.List;
/** Immutable ordered net-margin evidence preserving all upstream spread evidence. */
final class BuyReplacementNetMarginEvaluationSet {
 private final BuyReplacementSpreadEligibilityAssessment source; private final List<BuyReplacementNetMarginEvaluation> evaluations; private final long evaluatedAt;
 BuyReplacementNetMarginEvaluationSet(BuyReplacementSpreadEligibilityAssessment s,List<BuyReplacementNetMarginEvaluation> e,long at){source=s;evaluations=Collections.unmodifiableList(new ArrayList<>(e));evaluatedAt=at;}
 String getIntentId(){return source.getIntentId();} String getOriginalOfferIdentity(){return source.getOriginalOfferIdentity();} String getRecommendationId(){return source.getRecommendationId();} int getSlot(){return source.getSlot();} int getItemId(){return source.getItemId();} String getItemName(){return source.getItemName();} int getExactRemainderQuantity(){return source.getExactRemainderQuantity();} String getAppetiteName(){return source.getAppetiteName();} double getEffectiveHorizonHours(){return source.getEffectiveHorizonHours();} int getCurrentHighPrice(){return source.getCurrentHighPrice();} long getSpreadEvaluatedAt(){return source.getEvaluatedAt();} List<BuyReplacementSellPriceCandidate> getCandidates(){return source.getCandidates();} List<BuyReplacementPositiveSpreadCandidate> getPositiveSpreadCandidates(){return source.getPositiveSpreadCandidates();} List<BuyReplacementNetMarginEvaluation> getEvaluations(){return evaluations;} long getEvaluatedAt(){return evaluatedAt;}
}
